function imageTag(file, alt, cls="editorial-image") {
  return `<img class="${cls}" src="/images/${encodeURIComponent(file)}" alt="${esc(alt)}" loading="lazy" decoding="async">`;
}

function esc(value) {
  return String(value ?? "").replace(/[&<>"']/g, c => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;"
  })[c]);
}

